//! Agreement with the npm `proxy-addr` package, on its own terms.
//!
//! `fixtures/oracle.tsv` is generated by `scripts/fuzz/proxy-addr/gen.js`, which
//! drives npm `proxy-addr` (and the `forwarded` and `ipaddr.js` libraries it is
//! built on) over a generated corpus. The reference is what the crate
//! reimplements, so any disagreement is a bug in this crate.
//!
//! Each line names what it checks:
//!
//! * `FWD` — the raw forwarded list, peer first, independent of any trust spec.
//! * `ALL` — the chain of addresses up to the first untrusted hop.
//! * `ADDR` — the address the request is attributed to.
//!
//! A trust specification the reference rejects is recorded as `!<message>`. The
//! crate must reject it too, with the matching error variant, so rejection is
//! tested as hard as acceptance.

use std::net::IpAddr;
use std::str::FromStr;

use proxy_addr::{Error, Trust, addr, all, forwarded};

/// One line of the corpus: the tag, then the fields after it.
struct Case {
    tag: String,
    fields: Vec<String>,
}

fn cases() -> Vec<Case> {
    include_str!("fixtures/oracle.tsv")
        .lines()
        .filter(|line| !line.starts_with('#') && !line.trim().is_empty())
        .map(|line| {
            let mut fields: Vec<String> = line.split('\t').map(unescape).collect();
            let tag = fields.remove(0);
            Case { tag, fields }
        })
        .collect()
}

/// The inverse of the generator's escaping.
fn unescape(field: &str) -> String {
    if field == "\\N" {
        return String::new();
    }
    let mut out = String::with_capacity(field.len());
    let mut chars = field.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        match chars.next() {
            Some('t') => out.push('\t'),
            Some('n') => out.push('\n'),
            Some('\\') => out.push('\\'),
            // A trailing space is encoded so it survives a TSV round trip.
            Some('x') if chars.next() == Some('2') && chars.next() == Some('0') => out.push(' '),
            Some(other) => {
                out.push('\\');
                out.push(other);
            }
            None => out.push('\\'),
        }
    }
    out
}

fn ip(text: &str) -> IpAddr {
    IpAddr::from_str(text).unwrap_or_else(|_| panic!("peer is not an address: {text:?}"))
}

fn xff(case: &Case) -> Option<&str> {
    if case.fields[1] == "\\N" {
        None
    } else {
        Some(&case.fields[1])
    }
}

fn expected_error(message: &str) -> Error {
    if message.starts_with("invalid IP address") {
        let text = message.trim_start_matches("invalid IP address: ");
        Error::InvalidAddress(text.to_string())
    } else {
        let text = message.trim_start_matches("invalid range on address: ");
        Error::InvalidRange(text.to_string())
    }
}

#[test]
fn forwarded_list_matches_the_reference() {
    let mut checked = 0;
    for case in cases().iter().filter(|c| c.tag == "FWD") {
        let peer = ip(&case.fields[0]);
        let got = forwarded(peer, xff(case));
        let want: Vec<String> = case.fields[2..].to_vec();
        assert_eq!(got, want, "forwarded({peer}, {:?})", xff(case));
        checked += 1;
    }
    assert!(
        checked > 100,
        "the corpus looks truncated: {checked} FWD cases"
    );
}

#[test]
fn chain_and_address_match_the_reference() {
    let mut all_checked = 0;
    let mut addr_checked = 0;

    for case in cases().iter().filter(|c| c.tag == "ALL" || c.tag == "ADDR") {
        let peer = ip(&case.fields[0]);
        let header = xff(case);
        let specs: Vec<&str> = case.fields[2].split('|').collect();
        let tail: &str = &case.fields[3];

        let compiled = Trust::parse_list(specs.iter().copied());

        if let Some(message) = tail.strip_prefix('!') {
            let want = expected_error(message);
            assert_eq!(
                compiled.err(),
                Some(want),
                "{} with trust {:?} should be rejected",
                case.tag,
                case.fields[2]
            );
            continue;
        }

        let trust = compiled.unwrap_or_else(|e| {
            panic!(
                "{} with trust {:?} was rejected: {e}",
                case.tag, case.fields[2]
            )
        });

        if case.tag == "ALL" {
            let want: Vec<String> = case.fields[3..].to_vec();
            assert_eq!(
                all(peer, header, Some(&trust)),
                want,
                "all({peer}, {header:?}, {:?})",
                case.fields[2]
            );
            all_checked += 1;
        } else {
            assert_eq!(
                addr(peer, header, &trust),
                tail,
                "addr({peer}, {header:?}, {:?})",
                case.fields[2]
            );
            addr_checked += 1;
        }
    }

    assert!(
        all_checked > 1000,
        "the corpus looks truncated: {all_checked} ALL cases"
    );
    assert!(
        addr_checked > 1000,
        "the corpus looks truncated: {addr_checked} ADDR cases"
    );
}
